const messages = $input.all().map((item) => item.json).filter((message) => !message.author?.bot && String(message.channel_id || '') === '1529722358309584987' && /^!(vocab|vocab-batch)\s+/i.test(String(message.content || '').trim())).sort((a, b) => String(a.id).localeCompare(String(b.id)));
if (!messages.length) return [];
const message = messages[0];
const content = String(message.content || '').trim().normalize('NFKC');
const match = content.match(/^!(vocab|vocab-batch)\s+([\s\S]+)$/i);
let payload;
try { payload = JSON.parse(match[2].replace(/^```(?:json)?\s*|\s*```$/gi, '')); } catch { throw new Error('NON_RETRYABLE: payload must be valid JSON'); }
const rawEntries = match[1].toLowerCase() === 'vocab' ? [payload] : payload;
if (!Array.isArray(rawEntries) || rawEntries.length < 1 || rawEntries.length > 50) throw new Error('NON_RETRYABLE: batch must contain 1-50 entries');
const text = (value) => typeof value === 'string' ? value.trim().normalize('NFKC') : '';
const safe = (value) => /^[=+\-@]/.test(value) ? `'${value}` : value;
const hash = (value) => { let result = 2166136261; for (let index = 0; index < value.length; index++) { result ^= value.charCodeAt(index); result = Math.imul(result, 16777619); } return (result >>> 0).toString(16).padStart(8, '0'); };
const entries = rawEntries.map((raw, index) => {
  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) throw new Error(`NON_RETRYABLE: entry ${index + 1} must be an object`);
  const word = text(raw.word);
  const meaning = text(raw.meaning);
  const context = text(raw.context);
  if (!word) throw new Error(`NON_RETRYABLE: entry ${index + 1} requires word`);
  if (word.length > 120 || meaning.length > 1000 || context.length > 1000) throw new Error(`NON_RETRYABLE: entry ${index + 1} exceeds field length`);
  const normalizedWord = word.toLocaleLowerCase('en-US');
  const dedupeKey = `discord:${hash([normalizedWord, meaning.toLocaleLowerCase('vi-VN'), context.toLocaleLowerCase('vi-VN')].join('\u001f'))}`;
  return { content_id: `discord-${message.id}-${index}`, word: safe(word), normalized_word: safe(normalizedWord), language: 'en', part_of_speech: safe(text(raw.part_of_speech)), sense_key: '', meaning_vi: safe(meaning), context_topic: safe(context), example_en: safe(text(raw.example_en)), example_vi: safe(text(raw.example_vi)), ipa: safe(text(raw.ipa)), source: 'discord', source_ref: `${message.id}:${index}`, publish_ok: '', review_status: 'needs_review', status: 'needs_review', dedupe_key: dedupeKey, created_at: new Date().toISOString(), updated_at: new Date().toISOString(), source_message_id: String(message.id), source_channel_id: String(message.channel_id), source_user_id: String(message.author?.id || '') };
});
return [{ json: { message_id: String(message.id), channel_id: String(message.channel_id), user_id: String(message.author?.id || ''), entries } }];

const request = $('Select One Vocabulary Message').first().json;
const matrix = $input.first().json.data || [];
const headers = matrix[0] || [];
const rows = matrix.slice(1).filter((row) => Array.isArray(row) && row.some((value) => value !== ''));
const column = (name) => headers.indexOf(name);
const sourceRefs = new Set(rows.map((row) => String(row[column('source_ref')] || '')));
const dedupeKeys = new Set(rows.map((row) => String(row[column('dedupe_key')] || '')));
const entry = request.entries.find((candidate) => !sourceRefs.has(candidate.source_ref) && !dedupeKeys.has(candidate.dedupe_key));
if (!entry) return [];
return [{ json: { ...entry, hook: '', cta: '', template_id: '', license_note: '', reviewed_by: '', publish_at: '', claimed_at: '', render_id: '', publish_id: '', published_at: '', error_code: '' } }];
